package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.enums.*;

class CancelledFactualIntegrationTests extends CancellationRegularizationSupport {
    @org.springframework.beans.factory.annotation.Autowired com.pet.buscaativa.config.AgendaHorarioProperties grid;
    @ParameterizedTest @CsvSource({"PRESENTE,owner,200","FALTOU,owner,200","PRESENTE,admin,200","FALTOU,admin,200","PRESENTE,colleague,403","FALTOU,colleague,403","PRESENTE,reception,403","FALTOU,reception,403","PRESENTE,foreign,404","FALTOU,foreign,404"})
    void rf01To06And18To20CanceledFactIsExplicitAndDoesNotOccupyVacancy(FrequenciaAssistencial result,String role,int expected) throws Exception {var a=canceled(false);var actor=actor(role);var before=database();long rows=appointments.count(),events=history.count(),audits=regularizations.count(),clinicalAudits=corrections.count();var response=factual(actor,a,fact(a,result));assertEquals(expected,businessStatus(response),response.getContentAsString());if(expected!=200){assertEquals(before,database());return;}assertCanceledFact(a,result);assertEquals(rows,appointments.count());assertEquals(events+1,history.count());assertEquals(audits+1,regularizations.count());assertEquals(clinicalAudits,corrections.count());assertEquals(result.name(),json.readTree(response.getContentAsString()).get("frequenciaAssistencial").asText());assertEquals("CANCELADO",json.readTree(response.getContentAsString()).get("situacaoAtendimento").asText());var h=jdbc.queryForMap("select * from tb_historico_paciente where agendamento_id=? and tipo in ('PRESENCA','FALTA')",a.getId());assertEquals(result==FrequenciaAssistencial.PRESENTE?"PRESENCA":"FALTA",h.get("TIPO"));assertEquals(professional.getId(),h.get("PROFISSIONAL_ID"));assertEquals(LocalDateTime.of(a.getDataAgendamento(),a.getHoraAtendimento()),((java.sql.Timestamp)h.get("OCORRIDO_EM")).toLocalDateTime());assertEquals(a.getVersion()+1,appointment(a.getId()).getVersion());var p=patients.findById(patient.getId()).orElseThrow();if(result==FrequenciaAssistencial.PRESENTE){assertEquals(a.getDataAgendamento(),p.getDataUltimaPresenca());assertEquals(0,p.getCountFaltas());}else assertEquals(1,p.getCountFaltas());var audit=jdbc.queryForMap("select * from tb_auditoria_regularizacao_cancelamento where agendamento_id=?",a.getId());assertEquals("REGISTRO_FATO_ASSISTENCIAL",audit.get("TIPO_REGULARIZACAO"));assertEquals("NAO_REGISTRADA",audit.get("FREQUENCIA_ANTERIOR"));assertEquals(result.name(),audit.get("FREQUENCIA_RESULTANTE"));assertEquals("CANCELADA",audit.get("RESERVA_RESULTANTE"));assertEquals(actor.getId(),audit.get("ATOR_ID"));}
    @ParameterizedTest @CsvSource({"14:59,422","15:00,422","15:01,200"})
    void rf13And14FactualRegistrationIsStrictlyAfterSlot(String time,int expected) throws Exception {var a=canceled(true);now(DAY.atTime(LocalTime.parse(time)));var before=database();assertEquals(expected,factual(a,FrequenciaAssistencial.PRESENTE));if(expected!=200)assertEquals(before,database());}
    @ParameterizedTest @ValueSource(strings={"zero","blocked","changed_shift","no_offer","grid","full"})
    void rf07To09HistoricalFactDoesNotDependOnCurrentOffer(String change) throws Exception {var a=canceled(false);int interval=grid.getIntervaloMinutos();try{tx(()->{if(change.equals("grid"))grid.setIntervaloMinutos(45);if(change.equals("full")){capacity(professional,a.getDataAgendamento(),TurnoEnum.MANHA,1);seed(other,professional,SituacaoAtendimento.AGENDADO,a.getDataAgendamento(),"09:00");}if(change.equals("zero"))capacity(professional,a.getDataAgendamento(),TurnoEnum.MANHA,0);if(change.equals("changed_shift"))capacity(professional,a.getDataAgendamento(),TurnoEnum.TARDE,10);if(change.equals("blocked")){var b=new BloqueioAgenda();b.setUsuario(professional);b.setDataInicio(a.getDataAgendamento());b.setDataFim(a.getDataAgendamento());b.setMotivoBloqueio("Bloqueio sintético posterior.");blocks.saveAndFlush(b);}return null;});assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));assertCanceledFact(a,FrequenciaAssistencial.PRESENTE);}finally{grid.setIntervaloMinutos(interval);}}
    @Test void ih09And10SubsequentCorrectionsRequireTrustedOriginAndKeepBothAudits() throws Exception {var a=canceled(false);long rows=appointments.count(),events=history.count(),reg=regularizations.count(),cor=corrections.count();assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));var ids=jdbc.queryForList("select id from tb_historico_paciente where agendamento_id=? order by id",Long.class,a.getId());for(var target:List.of(FrequenciaAssistencial.FALTOU,FrequenciaAssistencial.PRESENTE,FrequenciaAssistencial.FALTOU)){a=appointment(a.getId());assertEquals(200,correct(admin,a,target));assertCanceledFact(a,target);assertEquals(ids,jdbc.queryForList("select id from tb_historico_paciente where agendamento_id=? order by id",Long.class,a.getId()));}assertEquals(rows,appointments.count());assertEquals(events+1,history.count());assertEquals(reg+1,regularizations.count());assertEquals(cor+3,corrections.count());a=appointment(a.getId());var before=database();assertEquals(200,correct(professional,a,FrequenciaAssistencial.FALTOU));assertEquals(before,database());}
    @Test void repeatedFactualRequestWithOldOrFreshVersionDoesNotDuplicateAnything() throws Exception {var a=canceled(false);assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));var before=database();assertEquals(409,factual(a,FrequenciaAssistencial.PRESENTE));assertEquals(409,factual(appointment(a.getId()),FrequenciaAssistencial.PRESENTE));assertEquals(before,database());}
    @Test void canceledPresenceIsClinicalButNeverOccupiesSlotAndBlocksAnotherIncompatibleFact() throws Exception {var a=canceled(false);assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));assertEquals(0,appointments.contarVagasOcupadasBySituacoes(professional,a.getDataAgendamento(),TurnoEnum.MANHA,List.of(SituacaoAtendimento.AGENDADO,SituacaoAtendimento.REMARCADO,SituacaoAtendimento.PRESENTE)));var b=tx(()->seed(other,professional,SituacaoAtendimento.CANCELADO,a.getDataAgendamento(),"08:00"));var before=database();var r=factual(admin,b,fact(b,FrequenciaAssistencial.PRESENTE));assertEquals(409,r.getStatus());assertEquals("CONFLITO_ASSISTENCIAL_PENDENTE_RECONCILIACAO",json.readTree(r.getContentAsString()).get("codigo").asText());assertEquals(before,database());}
    @Test void oldCanceledFactHasNoArbitraryRetroactiveLimit() throws Exception {var first=canceled(false);var id=first.getId();var a=tx(()->{var x=appointment(id);x.setDataAgendamento(DAY.minusMonths(8));return appointments.saveAndFlush(x);});assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));assertEquals(DAY.minusMonths(8),patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());assertCanceledFact(a,FrequenciaAssistencial.PRESENTE);}
}
